<template>
  <section class="signature-page">
    <header class="hero"><div><p class="eyebrow">STORY AGENT · STAGE 8 · ED25519 REVIEW SIGNATURE</p><h2>三角色盲评签名检查</h2><p>重算v2盲评decision，绑定review bundle、片型权重合同与三角色Ed25519签名；信任策略只从仓库读取。</p></div><RouterLink to="/story/stage8-blind-review-intake">返回盲评接入</RouterLink></header>
    <div class="truth-lock"><strong>验签 Ready ≠ 真人盲评通过</strong><span>页面不签名、不落盘、不启动finalization、不创建signed release，也不授予专业通过。</span></div>
    <p v-if="errorMessage" class="error-banner">{{ errorMessage }}</p>
    <template v-if="workspace && inspection">
      <section class="summary-grid"><article><span>项目</span><strong>75</strong></article><article><span>Trust policy</span><strong>{{ workspace.trust_policy.status }}</strong></article><article><span>Trusted</span><strong>{{ workspace.summary.trusted_reviewer_count }}/3</strong></article><article><span>Threshold Ready</span><strong>{{ workspace.summary.score_threshold_ready_project_count }}</strong></article><article><span>Signature Ready</span><strong>{{ workspace.summary.signature_verification_ready_project_count }}</strong></article><article class="zero"><span>真人 / 专业通过</span><strong>0 / 0</strong></article></section>
      <section class="toolbar"><label>固定项目<select v-model="selectedBenchmarkId" @change="reload"><option v-for="project in workspace.projects" :key="project.benchmark_id" :value="project.benchmark_id">{{ project.video_type }} · {{ project.benchmark_id }}</option></select></label><button :disabled="validating" @click="validate">{{ validating ? '校验中' : '仅验证签名' }}</button></section>
      <section class="editor-grid"><article><header><h3>Review Bundle v2</h3><button @click="copy(bundleRaw)">复制</button></header><textarea v-model="bundleRaw" aria-label="Stage 8 blind review bundle JSON" spellcheck="false" /></article><article><header><h3>Signature Attestation</h3><button @click="copy(signatureRaw)">复制</button></header><textarea v-model="signatureRaw" aria-label="Stage 8 blind review signature JSON" spellcheck="false" /></article></section>
      <section class="result-grid"><article class="checks"><header><div><p class="eyebrow">FAIL-CLOSED CHECKS</p><h3>{{ inspection.signature_verification_ready ? '签名验证Ready' : '外部材料未就绪' }}</h3></div><b :class="inspection.signature_verification_ready ? 'ready' : 'blocked'">{{ passedChecks }}/{{ checkEntries.length }}</b></header><div><p v-for="[key,value] in checkEntries" :key="key"><i :class="value ? 'ok' : 'no'">{{ value ? '✓' : '×' }}</i><span>{{ checkLabel(key) }}</span></p></div></article><article class="evidence"><p class="eyebrow">ZERO-CREDIT EVIDENCE</p><h3>验签摘要</h3><dl><div><dt>签名</dt><dd>{{ inspection.signature_summary.signature_count }}/3</dd></div><div><dt>可信reviewer</dt><dd>{{ inspection.signature_summary.trusted_reviewer_count }}</dd></div><div><dt>Payload digest</dt><dd>{{ inspection.signature_summary.payload_digest_match_count }}</dd></div><div><dt>Ed25519 verified</dt><dd>{{ inspection.signature_summary.cryptographically_verified_signature_count }}</dd></div><div><dt>Score threshold</dt><dd>{{ inspection.decision_summary.score_threshold_passed ? '通过' : '未通过' }}</dd></div><div><dt>真人信用</dt><dd>0</dd></div></dl><div class="safety"><span>Signature created <b>否</b></span><span>Persisted <b>否</b></span><span>Finalization <b>否</b></span><span>Human pass <b>否</b></span><span>Signed release <b>否</b></span><span>Professional pass <b>否</b></span></div></article></section>
    </template>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { Stage8BlindReviewSignatureInspectionResult, Stage8BlindReviewSignatureWorkspace } from '@shared/types'
import { getStage8BlindReviewSignatureWorkspace, validateStage8BlindReviewSignature } from '../api/stage8-blind-review'
const workspace=ref<Stage8BlindReviewSignatureWorkspace|null>(null),inspection=ref<Stage8BlindReviewSignatureInspectionResult|null>(null),selectedBenchmarkId=ref(''),bundleRaw=ref(''),signatureRaw=ref(''),errorMessage=ref(''),validating=ref(false)
const checkEntries=computed(()=>Object.entries(inspection.value?.checks??{})),passedChecks=computed(()=>checkEntries.value.filter(([,value])=>value).length)
onMounted(()=>reload())
async function reload(){const response=await getStage8BlindReviewSignatureWorkspace(selectedBenchmarkId.value);if(!response.ok||!response.data){errorMessage.value=response.error?.message??'签名工作台加载失败';return}workspace.value=response.data;selectedBenchmarkId.value=response.data.selected_benchmark_id;bundleRaw.value=response.data.review_bundle_template_raw_json;signatureRaw.value=response.data.signature_template_raw_json;inspection.value=response.data.template_inspection}
async function validate(){validating.value=true;errorMessage.value='';try{const response=await validateStage8BlindReviewSignature({expected_benchmark_id:selectedBenchmarkId.value,review_bundle_raw_json:bundleRaw.value,signature_raw_json:signatureRaw.value});if(!response.ok||!response.data){errorMessage.value=response.error?.message??'签名验证失败';return}inspection.value=response.data}finally{validating.value=false}}
async function copy(value:string){try{await navigator.clipboard.writeText(value)}catch{errorMessage.value='浏览器未授权复制'}}
const labels:Record<string,string>={request_valid:'请求完整',review_bundle_json_valid:'Bundle JSON',review_bundle_schema_valid:'Bundle v2 schema',registry_binding_valid:'固定项目绑定',score_threshold_passed:'分数阈值',score_threshold_is_not_human_credit:'阈值零信用',trust_policy_schema_valid:'Trust schema',trust_policy_active:'Trust active',signature_attestation_json_valid:'Attestation JSON',signature_attestation_schema_valid:'Attestation schema',benchmark_binding_valid:'Benchmark绑定',video_type_binding_valid:'片型绑定',run_id_binding_valid:'Run绑定',review_bundle_digest_binding_valid:'Bundle digest',decision_digest_binding_valid:'Decision digest',weight_contract_digest_binding_valid:'权重合同digest',score_threshold_binding_valid:'阈值状态绑定',required_roles_signed:'三角色签名',trusted_reviewer_bindings_valid:'可信reviewer绑定',signed_payload_digests_valid:'签名payload digest',cryptographic_signatures_valid:'Ed25519验签',signature_timestamps_valid:'签名时间',source_claimed_credit_rejected:'拒绝自报信用'}
function checkLabel(key:string){return labels[key]??key}
</script>

